<?php
ini_set('display_errors','0'); error_reporting(E_ALL); header('Cache-Control: no-store');
require __DIR__.'/../../lib/Db.php'; require __DIR__.'/../../lib/Jwt.php';
$CONFIG=require __DIR__.'/../../config.php';
function failx($m,$s=400){http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode(['error'=>$m],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function userx(){global $CONFIG;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))failx('توکن نامعتبر است',401);$p=Jwt::verify(trim($m[1]),$CONFIG['jwt_secret']);if(!$p)failx('توکن منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])failx('کاربر نامعتبر است',401);return $u;}
function adminx($u){return !empty($u['is_admin'])||in_array($u['role_title']??'', ['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true);}
function col($n){$s='';do{$s=chr(65+$n%26).$s;$n=intdiv($n,26)-1;}while($n>=0);return $s;}
function xe($v){return htmlspecialchars((string)($v??''),ENT_XML1|ENT_QUOTES,'UTF-8');}
function cell($ref,$value,$style=0){return '<c r="'.$ref.'" t="inlineStr" s="'.$style.'"><is><t>'.xe($value).'</t></is></c>';}
function numcell($ref,$value,$style=0){return '<c r="'.$ref.'" t="n" s="'.$style.'"><v>'.xe($value).'</v></c>';}
function ensure_export_schema(){
  Db::run("CREATE TABLE IF NOT EXISTS line_station_locations (id BIGINT AUTO_INCREMENT PRIMARY KEY,line_id INT NOT NULL,station_code VARCHAR(80) NULL,station_status VARCHAR(30) NOT NULL DEFAULT 'registered',station_name VARCHAR(190) NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,accuracy_m DECIMAL(10,2) NULL,physical_address TEXT NULL,street VARCHAR(190) NULL,location_photo_path VARCHAR(500) NULL,captured_by INT NOT NULL,captured_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_lsl_line(line_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
  Db::run("CREATE TABLE IF NOT EXISTS line_station_signs (id BIGINT AUTO_INCREMENT PRIMARY KEY,station_location_id BIGINT NOT NULL,sign_type_id INT NOT NULL,photo_path VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_lss_station(station_location_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
$u=userx();if(!adminx($u))failx('دسترسی خروجی خطوط و ایستگاه‌ها ندارید',403);if(!class_exists('ZipArchive'))failx('ZipArchive روی سرور فعال نیست',500);
try{ensure_export_schema();$rows=Db::all("SELECT l.id line_id,l.code line_code,l.origin,l.destination,l.status line_status,l.latitude line_latitude,l.longitude line_longitude,l.location_accuracy_m line_accuracy,l.station_name line_station_name,l.station_physical_address,l.station_street,s.id station_id,s.station_code,s.station_status,s.station_name,s.latitude,s.longitude,s.accuracy_m,s.physical_address,s.street,s.location_photo_path,s.captured_at,TRIM(CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,''))) captured_by,GROUP_CONCAT(DISTINCT t.title ORDER BY t.sort_order,t.title SEPARATOR '، ') sign_types,GROUP_CONCAT(DISTINCT sg.photo_path ORDER BY sg.id SEPARATOR ' | ') sign_photos FROM `lines` l LEFT JOIN line_station_locations s ON s.id=(SELECT MAX(s2.id) FROM line_station_locations s2 WHERE s2.line_id=l.id) LEFT JOIN line_station_signs sg ON sg.station_location_id=s.id LEFT JOIN station_sign_types t ON t.id=sg.sign_type_id LEFT JOIN users u ON u.id=s.captured_by GROUP BY l.id,s.id ORDER BY l.code,l.id");}catch(Throwable $e){failx('خواندن خطوط و ایستگاه‌ها ناموفق بود: '.$e->getMessage(),500);}
$tmp=tempnam(sys_get_temp_dir(),'khs');$z=new ZipArchive();if($z->open($tmp,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)failx('ساخت Excel ناموفق بود',500);
$heads=['ردیف','شناسه خط','شماره خط','مبدأ','مقصد','وضعیت خط','شناسه ثبت ایستگاه','شناسه ایستگاه','وضعیت ایستگاه','نام ایستگاه','عرض جغرافیایی','طول جغرافیایی','دقت GPS (متر)','آدرس فیزیکی','خیابان','تصویر محل','ثبت‌کننده','تاریخ ثبت','نوع تابلوها','تصاویر تابلو'];$sd='<row r="1">';foreach($heads as $i=>$h)$sd.=cell(col($i).'1',$h,1);$sd.='</row>';
foreach($rows as $i=>$r){$rn=$i+2;$sd.='<row r="'.$rn.'">';$status=($r['station_status']??'')==='missing'?'ناموجود':(($r['station_id']??'')?'ثبت‌شده':'ثبت نشده');$v=[$i+1,$r['line_id']??'',$r['line_code']??'',$r['origin']??'',$r['destination']??'',$r['line_status']??'',$r['station_id']??'',$r['station_code']??'',$status,$r['station_name']??($r['line_station_name']??''),$r['latitude']??$r['line_latitude']??'',$r['longitude']??$r['line_longitude']??'',$r['accuracy_m']??$r['line_accuracy']??'',$r['physical_address']??$r['station_physical_address']??'',$r['street']??$r['station_street']??'',$r['location_photo_path']??'',$r['captured_by']??'',$r['captured_at']??'',$r['sign_types']??'',$r['sign_photos']??''];foreach($v as $j=>$x){if(($j===0||$j===1||$j===6||$j===7)&&$x!=='')$sd.=numcell(col($j).$rn,$x);elseif(in_array($j,[10,11,12],true)&&$x!==''&&is_numeric($x))$sd.=numcell(col($j).$rn,$x);else $sd.=cell(col($j).$rn,$x);}$sd.='</row>';}
$last=max(1,count($rows)+1);$sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView rightToLeft="1" workbookViewId="0"/></sheetViews><cols><col min="1" max="2" width="12"/><col min="3" max="6" width="20"/><col min="7" max="9" width="18"/><col min="10" max="10" width="24"/><col min="11" max="13" width="18"/><col min="14" max="16" width="32"/><col min="17" max="18" width="24"/><col min="19" max="20" width="32"/></cols><sheetData>'.$sd.'</sheetData><autoFilter ref="A1:T'.$last.'"/></worksheet>';
$z->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
$z->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
$z->addFromString('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="خطوط و ایستگاه‌ها" sheetId="1" r:id="rId1"/></sheets></workbook>');
$z->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
$z->addFromString('xl/styles.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Arial"/></font><font><b/><sz val="11"/><name val="Arial"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF6C324"/></patternFill></fill></fills><borders count="1"><border/></borders><cellXfs count="2"><xf/><xf fontId="1" fillId="1"/></cellXfs></styleSheet>');
$z->addFromString('xl/worksheets/sheet1.xml',$sheet);$z->close();
$name='khatyar-lines-stations-'.date('Ymd-His').'.xlsx';header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($tmp));header('Cache-Control: no-store, no-cache, must-revalidate');readfile($tmp);@unlink($tmp);
